def taller_within(a: list[int], k: int) -> list[int]:
    if k == 0:
        return [0] * len(a)

    ranks = {value: i + 1 for i, value in enumerate(sorted(set(a)))}
    tree = [0] * (len(ranks) + 1)
    result = []
    window_size = 0

    for i, height in enumerate(a):
        if i > k:
            rank = ranks[a[i - k - 1]]
            while rank < len(tree):
                tree[rank] -= 1
                rank += rank & -rank
            window_size -= 1

        rank = ranks[height]
        count_at_most = 0
        index = rank
        while index:
            count_at_most += tree[index]
            index -= index & -index

        result.append(window_size - count_at_most)

        while rank < len(tree):
            tree[rank] += 1
            rank += rank & -rank
        window_size += 1

    return result
